// Command syskit is a small CLI that reports host details gathered through
// low-level system calls which the Go standard library does not wrap.
package main

import (
	"encoding/json"
	"flag"
	"fmt"
	"os"

	"example.com/syskit/internal/platform"
)

func main() {
	asJSON := flag.Bool("json", false, "emit the result as JSON")
	flag.Parse()

	info, err := platform.Info()
	if err != nil {
		fmt.Fprintf(os.Stderr, "syskit: %v\n", err)
		os.Exit(1)
	}

	if *asJSON {
		enc := json.NewEncoder(os.Stdout)
		enc.SetIndent("", "  ")
		if err := enc.Encode(info); err != nil {
			fmt.Fprintf(os.Stderr, "syskit: %v\n", err)
			os.Exit(1)
		}
		return
	}

	fmt.Printf("os:      %s\n", info.OS)
	fmt.Printf("release: %s\n", info.Release)
	fmt.Printf("version: %s\n", info.Version)
	fmt.Printf("machine: %s\n", info.Machine)
}

// Package platform exposes host details gathered through low-level system
// calls that the Go standard library does not wrap.
//
// Each supported operating system provides its own Info implementation in a
// file guarded by a build constraint. The exported API is identical across
// platforms, so callers never need to be aware of the underlying mechanism.
package platform

// Info describes the host operating system.
type Info struct {
	OS      string `json:"os"`
	Release string `json:"release"`
	Version string `json:"version"`
	Machine string `json:"machine"`
}

//go:build linux

package platform

import "golang.org/x/sys/unix"

// Info reports host details using the uname(2) system call.
func Info() (Info, error) {
	var uts unix.Utsname
	if err := unix.Uname(&uts); err != nil {
		return Info{}, err
	}
	return Info{
		OS:      unix.ByteSliceToString(uts.Sysname[:]),
		Release: unix.ByteSliceToString(uts.Release[:]),
		Version: unix.ByteSliceToString(uts.Version[:]),
		Machine: unix.ByteSliceToString(uts.Machine[:]),
	}, nil
}

//go:build darwin

package platform

import "golang.org/x/sys/unix"

// Info reports host details using the uname(2) system call.
func Info() (Info, error) {
	var uts unix.Utsname
	if err := unix.Uname(&uts); err != nil {
		return Info{}, err
	}
	return Info{
		OS:      unix.ByteSliceToString(uts.Sysname[:]),
		Release: unix.ByteSliceToString(uts.Release[:]),
		Version: unix.ByteSliceToString(uts.Version[:]),
		Machine: unix.ByteSliceToString(uts.Machine[:]),
	}, nil
}

//go:build windows

package platform

import (
	"fmt"
	"runtime"

	"golang.org/x/sys/windows"
)

// Info reports host details using the ntdll RtlGetNtVersionNumbers call,
// which bypasses the shim layer used by the standard library's version APIs.
func Info() (Info, error) {
	major, minor, build := windows.RtlGetNtVersionNumbers()
	build &= 0xffff // RtlGetNtVersionNumbers sets the high bits on some builds.
	return Info{
		OS:      "Windows",
		Release: fmt.Sprintf("%d.%d", major, minor),
		Version: fmt.Sprintf("build %d", build),
		Machine: runtime.GOARCH,
	}, nil
}

//go:build !linux && !darwin && !windows

package platform

import (
	"errors"
	"fmt"
	"runtime"
)

// ErrUnsupported is returned on operating systems without a low-level
// implementation.
var ErrUnsupported = errors.New("platform: unsupported operating system")

// Info returns ErrUnsupported on platforms that have no implementation.
func Info() (Info, error) {
	return Info{}, fmt.Errorf("%w: %s", ErrUnsupported, runtime.GOOS)
}

// Package platform exposes host details gathered through low-level system
// calls that the Go standard library does not wrap.
//
// Each supported operating system provides its own Info implementation in a
// file guarded by a build constraint. The exported API is identical across
// platforms, so callers never need to be aware of the underlying mechanism.
package platform

// SystemInfo describes the host operating system.
type SystemInfo struct {
	OS      string `json:"os"`
	Release string `json:"release"`
	Version string `json:"version"`
	Machine string `json:"machine"`
}

